// Shared Rust cooked-string continuation and source line-break decisions.
// Native Rust is generated by js/scripts/generate-rust-string-rules.mjs.
// Rust Reference: expr.literal.continuation and expr.literal.string-representation.
// https://doc.rust-lang.org/reference/expressions/literal-expr.html#string-continuation-escapes
// Inputs are UTF-16 code units. Results index the original, unnormalized source.

/** @param {number} [unit] @returns {boolean} */
export function acceptRustStringContinuationWhitespace(unit) {
  return unit === 9 || unit === 10 || unit === 13 || unit === 32;
}

/**
 * Read backslash plus LF, or the source-level CRLF spelling of LF, and only
 * the four continuation whitespace units. A negative result rejects the prefix.
 * @param {number[]} units @param {number} start @returns {number}
 */
export function readRustStringContinuationEnd(units, start) {
  if (start < 0 || start >= units.length || start % 1 !== 0 || units[start] !== 92) return -1;
  let end = start + 1;
  if (units[end] === 13 && units[end + 1] === 10) end += 1;
  if (units[end] !== 10) return -1;
  end += 1;
  while (end < units.length && acceptRustStringContinuationWhitespace(units[end])) end += 1;
  return end;
}

/**
 * Rust normalizes source CRLF into LF before interpreting literal values.
 * Return the original source end, or a negative result for another spelling.
 * @param {number[]} units @param {number} start @returns {number}
 */
export function readRustSourceLineBreakEnd(units, start) {
  if (start < 0 || start >= units.length || start % 1 !== 0) return -1;
  return units[start] === 13 && units[start + 1] === 10 ? start + 2 : -1;
}
